changeSet.sql:
ALTER TABLE welcome_centers ADD COLUMN IF NOT EXISTS status VARCHAR(6) DEFAULT 'OPEN';
UPDATE welcome_centers SET status = 'OPEN' WHERE status IS NULL;
ALTER TABLE welcome_centers ALTER COLUMN status SET DEFAULT 'OPEN';
ALTER TABLE welcome_centers ALTER COLUMN status SET NOT NULL;
ALTER TABLE welcome_centers ADD CONSTRAINT IF NOT EXISTS ck_welcome_center_status CHECK (status IN ('OPEN', 'CLOSED'));
